function loadKey(program,week,day,name){return [program,week,day,name].map(x=>String(x||'').trim().toLowerCase()).join('|')}
function weeklyItem(source,day,week=state.week){const it={...source};const wk=Number(week)||1;const override=state.weekLoads?.[loadKey(active().name,wk,day,it.name)];if(Number(override)>0){it.loadKg=Number(override);it.pct=0;it.planNote=[it.planNote,'Progressed from previous week'].filter(Boolean).join(' · ');return it}const w=Math.max(1,Math.min(12,Number(week)||1)),i=w-1,n=it.name.toLowerCase();const engine=active()?.progressionEngine||'off';if(engine==='off')return it;if(engine!=='builtin'){const custom=state.progressionEngines.find(e=>e.id===engine);if(!custom)return it;const rule=custom.weeks[Math.min(i,custom.weeks.length-1)]||{intensity:100,volume:100,focus:''};if(Number(rule.loadChangeKg||0)!==0){it.loadKg=Math.max(0,Number(it.loadKg||0)+Number(rule.loadChangeKg));it.pct=0;it.planNote=[rule.focus,rule.note,`Custom load change ${Number(rule.loadChangeKg)>0?'+':''}${Number(rule.loadChangeKg)} kg`].filter(Boolean).join(' · ');}else{it.pct=Math.round(Number(it.pct||0)*(Number(rule.intensity??100)/100)*2)/2;it.planNote=[rule.focus,rule.note].filter(Boolean).join(' · ');}it.sets=Math.max(1,Math.round((Number(it.sets)||1)*(Number(rule.volume??100)/100)));return it;}const isComplex=n.includes('complex'),isPull=n.includes('pull'),isSnatch=n.includes('snatch'),isCJ=n.includes('clean & jerk')||n.includes('clean and jerk'),isBack=n.includes('back squat'),isFront=n.includes('front squat'),isMainLift=(isSnatch||isCJ)&&!isComplex&&!isPull;
 if(/treadmill intervals/i.test(n)){const prescriptions=['Warm-up 5 min; 6 × 30 sec fast / 90 sec easy; cool down','Warm-up 5 min; 7 × 30 sec fast / 90 sec easy; cool down','Warm-up 5 min; 8 × 30 sec fast / 90 sec easy; cool down','Easy 15–18 min; 5 × 20 sec relaxed strides','Warm-up 5 min; 6 × 40 sec fast / 80–100 sec easy','Warm-up 5 min; 7 × 40 sec fast / 80–100 sec easy','Warm-up 5 min; 8 × 40 sec fast / 80–100 sec easy','Easy 15–18 min; 5 × 20 sec relaxed strides','Warm-up 5 min; 8 × 45 sec fast / 90 sec easy','Warm-up 5 min; 10 × 30 sec fast / 75–90 sec easy','Warm-up 5 min; 6 × 30 sec fast, full easy recovery','Easy 12–15 min; 4 × 15–20 sec relaxed strides'];it.sets=1;it.reps=prescriptions[i];it.planNote='Speed should be fast but controlled; all hard intervals are ≤45 seconds. Use your established treadmill speeds, not an all-out sprint.';return it;}
 if(/treadmill hills/i.test(n)){const prescriptions=['30 min total; 6 × 30 sec uphill, easy walk/jog recovery','32 min total; 7 × 30 sec uphill','34 min total; 8 × 30 sec uphill','25–30 min easy, no hard hills','35 min total; 6 × 40 sec uphill','38 min total; 7 × 40 sec uphill','40 min total; 8 × 40 sec uphill','28–32 min easy, no hard hills','40 min total; 8 × 45 sec uphill','42 min total; 9 × 40 sec uphill','35–40 min total; 6 × 45 sec high-quality uphill','25–30 min easy; optional 4 × 20 sec relaxed strides'];it.sets=1;it.reps=prescriptions[i];it.planNote='Include 5–8 min warm-up and 5 min cool-down; keep uphill efforts ≤45 seconds and recover fully.';return it;}
 if(isComplex){it.pct=PCT.complex[i];it.sets=([4,4,4,3,4,4,4,3,3,3,3,2])[i];it.planNote='Complex quality first: stop the set if positions or speed deteriorate.';return it;}
 if(isPull){it.pct=PCT.pull[i];it.sets=([3,3,3,2,3,3,3,2,3,3,2,2])[i];it.reps=(w===11?'2':w===12?'2–3':'3');it.planNote='Pull percentages use the corresponding lift reference max; prioritise bar speed and position.';return it;}
 if(isBack){const arr=day==='Monday'?PCT.backMon:day==='Wednesday'?PCT.backWed:PCT.backFri;it.pct=arr[i];if(day==='Monday'){it.sets=[4,4,4,3,5,5,5,3,4,4,3,2][i];it.reps=['4','4','4','3','3','3','3','3','2','2','1–2','3'][i]}else if(day==='Wednesday'){it.sets=[4,4,4,3,4,4,4,3,3,3,2,2][i];it.reps=['3','3','3','3','2–3','2–3','2','2','2','2','1–2','2'][i]}else{it.sets=[3,3,3,2,4,4,4,2,3,3,2,2][i];it.reps=['3','3','3','3','2','2','2','2','2','2','1','2'][i]}it.planNote='Use the prescribed load only if it matches the day’s readiness; leave reps in reserve and avoid grinders.';return it;}
 if(isFront){const arr=day==='Tuesday'?PCT.frontTue:PCT.frontThu;it.pct=arr[i];if(day==='Tuesday'){it.sets=[4,4,4,3,4,4,4,3,3,3,2,2][i];it.reps=['4','4','4','3','3','3','2–3','3','2','2','1–2','2'][i]}else{it.sets=Math.max(1,Math.round((Number(source.sets)||3)*CYCLE[i].accessory));it.reps=w===4||w===8?'6 easy':w>=9?'5–6':'6'}it.planNote=day==='Tuesday'?'Front squat strength progression. Keep bracing and depth consistent.':'Accessory front squat: controlled tempo; leave 2–3 reps in reserve.';return it;}
 if(isMainLift){it.pct=(isCJ?PCT.cj:PCT.snatch)[i];it.sets=[5,5,5,3,5,5,5,3,4,4,3,2][i];it.reps=['2','2','2','2','1–2','1–2','1–2','1','1','1','1','2'][i];it.planNote='Technical quality governs load. No planned misses; reduce load if bar speed or positions deteriorate.';return it;}
 // Bodybuilding and general accessories: keep exercise choice, reduce sets in deload/peak/taper weeks.
 it.sets=Math.max(1,Math.round((Number(source.sets)||3)*CYCLE[i].accessory));
 if(CYCLE[i].accessory<=.6)it.planNote='Reduced accessory volume this week; finish well short of failure.';
 else if(CYCLE[i].phase==='Peak')it.planNote='Maintain muscle and balance with low fatigue; leave 2–3 reps in reserve.';
 return it;
}
function phaseForWeek(week){return CYCLE[Math.max(1,Math.min(12,Number(week)||1))-1]}
function renderCycleEngine(){const el=document.getElementById('cycleEngine');if(!el)return;const p=active(),engine=p.progressionEngine||'off',w=activeWeek(),phase=phaseForWeek(w);const options=[['off','Off — manual programming'],['builtin','Built-in 12-week progression'],...state.progressionEngines.map(e=>[e.id,'Custom: '+e.name])].map(([v,label])=>`<option value="${esc(v)}" ${engine===v?'selected':''}>${esc(label)}</option>`).join('');let body=`<div class="field"><label for="progressionEngineSelect">Progression engine for this program</label><select id="progressionEngineSelect">${options}</select></div><div class="btnrow"><button class="btn" id="createCustomEngine">＋ Create custom engine</button></div>`;if(engine==='off'){body+=`<div class="notice">Progression is off for this program. Sets, reps and percentages stay as entered in the weekly plan. You can still change the training week manually.</div><div class="formgrid"><div class="field"><label>Current week (1–12)</label><input id="manualProgramWeek" type="number" min="1" max="12" value="${w}"></div><div class="field" style="justify-content:end"><button class="btn primary full" id="saveManualWeek">Save week</button></div></div>`;}else if(engine==='builtin'){const rows=CYCLE.map((x,i)=>`<tr><td style="padding:7px;border-bottom:1px solid var(--line)"><button class="btn ${w===i+1?'primary':'ghost'}" data-cycle-week="${i+1}" style="padding:6px 9px">${i+1}</button></td><td style="padding:7px;border-bottom:1px solid var(--line)">${esc(x.phase)}</td><td style="padding:7px;border-bottom:1px solid var(--line);color:var(--muted);font-size:12px">${esc(x.focus)}</td></tr>`).join('');body+=`<div class="exercisehead" style="margin-top:14px"><div><div class="eyebrow">BUILT-IN 12-WEEK ENGINE</div><h2 style="margin:4px 0">Week ${w} of 12 · ${esc(phase.phase)}</h2><div class="muted small">${esc(phase.focus)}</div></div><span class="badge">${Math.round(w/12*100)}%</span></div><div class="btnrow" style="margin:12px 0"><button class="btn" id="cyclePrev" ${w===1?'disabled':''}>← Previous</button><button class="btn primary" id="cycleNext" ${w===12?'disabled':''}>Next week →</button></div><div class="notice">This engine automatically adjusts supported exercise prescriptions by week. Week 12 is a taper/review, not a requirement to test a one-rep max.</div><details><summary style="cursor:pointer;padding:8px 0">View all 12 weeks</summary><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;text-align:left"><thead><tr><th style="padding:7px">Week</th><th style="padding:7px">Phase</th><th style="padding:7px">Focus</th></tr></thead><tbody>${rows}</tbody></table></div></details>`;}else{const custom=state.progressionEngines.find(e=>e.id===engine);if(custom){body+=`<div class="exercisehead" style="margin-top:14px"><div><div class="eyebrow">CUSTOM ENGINE</div><h2 style="margin:4px 0">${esc(custom.name)} · Week ${w} of 12</h2><div class="muted small">${esc(custom.weeks[w-1]?.phase||'Custom week')} · Intensity ${Number(custom.weeks[w-1]?.intensity??100)}% · Load change ${Number(custom.weeks[w-1]?.loadChangeKg||0)} kg · Volume ${Number(custom.weeks[w-1]?.volume??100)}%</div></div><span class="badge">${Math.round(w/12*100)}%</span></div><div class="btnrow" style="margin:12px 0"><button class="btn" id="cyclePrev" ${w===1?'disabled':''}>← Previous</button><button class="btn primary" id="cycleNext" ${w===12?'disabled':''}>Next week →</button><button class="btn ghost" id="editCustomEngine">Edit engine</button></div><div class="muted small">Intensity scales exercise percentages; volume scales prescribed sets. Exercise names, reps and manually entered prescriptions remain editable.</div><details><summary style="cursor:pointer;padding:8px 0">View custom 12-week plan</summary><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;text-align:left"><thead><tr><th style="padding:7px">Week</th><th style="padding:7px">Phase</th><th style="padding:7px">Intensity</th><th style="padding:7px">Load change</th><th style="padding:7px">Volume</th><th style="padding:7px">Focus / note</th></tr></thead><tbody>${custom.weeks.map((r,i)=>`<tr><td style="padding:7px;border-bottom:1px solid var(--line)">${i+1}</td><td style="padding:7px;border-bottom:1px solid var(--line)">${esc(r.phase||'')}</td><td style="padding:7px;border-bottom:1px solid var(--line)">${Number(r.intensity??100)}%</td><td style="padding:7px;border-bottom:1px solid var(--line)">${Number(r.loadChangeKg||0)} kg</td><td style="padding:7px;border-bottom:1px solid var(--line)">${Number(r.volume??100)}%</td><td style="padding:7px;border-bottom:1px solid var(--line)">${esc([r.focus,r.note].filter(Boolean).join(' · '))}</td></tr>`).join('')}</tbody></table></div></details>`;}else body+=`<div class="notice">This custom engine could not be found. Choose another engine.</div>`;}el.innerHTML=body;const select=document.getElementById('progressionEngineSelect');select.onchange=()=>{active().progressionEngine=select.value;save();render();toast('Progression setting saved for '+active().name)};document.getElementById('createCustomEngine').onclick=()=>openCustomEngineEditor();const prev=document.getElementById('cyclePrev'),next=document.getElementById('cycleNext');if(prev)prev.onclick=()=>setCycleWeek(w-1);if(next)next.onclick=()=>setCycleWeek(w+1);el.querySelectorAll('[data-cycle-week]').forEach(b=>b.onclick=()=>setCycleWeek(Number(b.dataset.cycleWeek)));const saveManual=document.getElementById('saveManualWeek');if(saveManual)saveManual.onclick=()=>setCycleWeek(document.getElementById('manualProgramWeek').value);const edit=document.getElementById('editCustomEngine');if(edit)edit.onclick=()=>openCustomEngineEditor(state.progressionEngines.find(e=>e.id===engine));} 
function openCustomEngineEditor(existing=null){const defaultWeeks=Array.from({length:12},(_,i)=>({phase:['Build','Build','Build','Deload','Strength','Strength','Strength','Deload','Peak','Peak','Peak','Taper'][i],intensity:[100,102.5,105,90,107.5,110,112.5,95,115,117.5,120,90][i],volume:[100,100,110,60,90,90,85,60,70,65,50,40][i],focus:['Establish baseline','Small progression','Highest build volume','Reduce fatigue','Increase intensity','Progress load','Hardest strength week','Recovery','Specificity','High specificity','Peak week','Taper and review'][i],note:''}));const engine=existing||{name:'',weeks:defaultWeeks};const body=`<div class="field"><label>Engine name</label><input id="customEngineName" value="${esc(engine.name)}" placeholder="e.g. 8-week strength build"></div><p class="muted small">Create a 12-week template. Intensity (%) scales percentage-based exercise prescriptions; Load change (kg) adds a fixed amount to the programmed kilogram load for that week (non-zero kg change takes precedence over intensity scaling); volume (%) scales sets. Use 100% intensity or 0 kg change for no change. Values are relative to the exercise prescription already in your plan.</p><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;text-align:left;min-width:620px"><thead><tr><th style="padding:6px">Week</th><th style="padding:6px">Phase</th><th style="padding:6px">Intensity %</th><th style="padding:6px">Load change kg</th><th style="padding:6px">Volume %</th><th style="padding:6px">Focus / note</th></tr></thead><tbody>${engine.weeks.map((r,i)=>`<tr data-custom-week="${i}" style="border-bottom:1px solid var(--line)"><td style="padding:6px">${i+1}</td><td style="padding:4px"><input data-custom="phase" value="${esc(r.phase||'Week '+(i+1))}" style="min-width:100px;padding:8px"></td><td style="padding:4px"><input data-custom="intensity" type="number" min="0" max="150" step="2.5" value="${Number(r.intensity??100)}" style="min-width:80px;padding:8px"></td><td style="padding:4px"><input data-custom="loadChangeKg" type="number" step="0.5" value="${Number(r.loadChangeKg||0)}" style="min-width:80px;padding:8px" title="Added to the exercise's programmed kg load; non-zero disables intensity scaling for that week"></td><td style="padding:4px"><input data-custom="volume" type="number" min="0" max="200" step="5" value="${Number(r.volume??100)}" style="min-width:80px;padding:8px"></td><td style="padding:4px"><input data-custom="focus" value="${esc(r.focus||r.note||'')}" placeholder="Optional note" style="min-width:140px;padding:8px"></td></tr>`).join('')}</tbody></table></div>`;modal(existing?'Edit custom engine':'Create custom progression engine',body,[{label:'Cancel',cls:'btn ghost',action:closeModal},{label:existing?'Save changes':'Create engine',cls:'btn primary',action:()=>{const name=document.getElementById('customEngineName').value.trim();if(!name)return toast('Enter an engine name');if(state.progressionEngines.some(e=>e.name.toLowerCase()===name.toLowerCase()&&e.id!==existing?.id))return toast('An engine with that name already exists');const weeks=[...document.querySelectorAll('[data-custom-week]')].map(row=>({phase:row.querySelector('[data-custom="phase"]').value.trim()||'Week',intensity:Math.max(0,Math.min(150,row.querySelector('[data-custom="intensity"]').value===''?100:Number(row.querySelector('[data-custom="intensity"]').value))),loadChangeKg:Number(row.querySelector('[data-custom="loadChangeKg"]')?.value)||0,volume:Math.max(0,Math.min(200,row.querySelector('[data-custom="volume"]').value===''?100:Number(row.querySelector('[data-custom="volume"]').value))),focus:row.querySelector('[data-custom="focus"]').value.trim(),note:''}));if(existing){existing.name=name;existing.weeks=weeks;}else{const id='custom-'+Date.now();state.progressionEngines.push({id,name,weeks});active().progressionEngine=id;}save();closeModal();render();toast(existing?'Custom engine updated':'Custom engine created and applied to this program');}}]);}
function setCycleWeek(week){const w=Math.max(1,Math.min(12,Number(week)||1));active().week=w;state.week=w;save();render();toast(`${active().name}: Week ${w} · ${phaseForWeek(w).phase}`)}
function weekLogs(week=activeWeek()){return state.logs.filter(l=>Number(l.week)===week&&(l.program===active().name||(!l.program&&active().name==='Combined training')))}
