 document.getElementById('wodAddExercise').onclick=add;rows.onclick=e=>{if(e.target.closest('[data-wod-remove]'))e.target.closest('.wod-row').remove()};document.getElementById('wodImage').onchange=e=>{document.getElementById('wodImageName').textContent=e.target.files?.[0]?.name||'No image selected'};add();
