async function saveWOD(){const rows=[...document.querySelectorAll('#wodRows .wod-row')],items=rows.map(r=>({name:r.querySelector('[data-wod=name]').value.trim(),sets:Math.max(1,Number(r.querySelector('[data-wod=sets]').value)||1),reps:r.querySelector('[data-wod=reps]').value.trim(),weight:Number(r.querySelector('[data-wod=weight]').value)||0,notes:r.querySelector('[data-wod=notes]').value.trim()})).filter(x=>x.name);if(!items.length){toast('Add at least one exercise to the WOD');return}const f=document.getElementById('wodImage')?.files?.[0],photoNote=f?await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)}):'',date=document.getElementById('wodDate').value||new Date().toISOString().slice(0,10),title=document.getElementById('wodName').value.trim()||'Workout Of the Day';items.forEach((it,i)=>state.logs.push({id:'wod-'+Date.now()+'-'+i,timestamp:new Date(date+'T12:00:00').getTime(),date,day:'WOD',week:activeWeek(),program:active().name,exercise:it.name,weight:it.weight,sets:it.sets,reps:it.reps,notes:[title,it.notes].filter(Boolean).join(' · '),type:'wod',photoNote:i===0?photoNote:'',done:true}));save();closeModal();render();toast('WOD saved: '+items.length+' exercise'+(items.length===1?'':'s'))}
function openWorkout(day){const d=active().days[day]||{items:[]};activeWorkout={day,program:active().name,items:(d.items||[]).map(it=>weeklyItem(it,day,activeWeek()))};const body=`<div class="formgrid"><div class="field"><label>Date</label><input type="date" id="logDate" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Training week</label><input type="number" min="1" max="12" id="logWeek" value="${window.viewedWeek||activeWeek()}"></div></div><div id="workoutExercises">${activeWorkout.items.map((it,i)=>workoutItemHTML(it,i)).join('')}</div><div class="notice">Enter actual work completed. For percentage-based lifts, the suggested load is rounded to your selected plate increment. Set a per-exercise “Next-week increase” in Program editing to carry the heaviest logged working weight plus that increment into the next week; prior logs remain unchanged. Warm-up sets are not included unless you add them.</div>`;modal('Log '+day+' workout',body,[{label:'Cancel',cls:'btn ghost',action:closeModal},{label:'Save session',cls:'btn primary',action:saveWorkout}]);document.querySelectorAll('[data-addset]').forEach(b=>b.onclick=()=>{const card=b.closest('.exercise'),n=card.querySelectorAll('.setrow').length+1;card.querySelector('.setrows').insertAdjacentHTML('beforeend',setRowHTML(n,Number(card.dataset.suggest)||0,1,!!card.querySelector('[data-field="reps"]')));bindSetRows(card)});document.querySelectorAll('[data-remove-ex]').forEach(b=>b.onclick=()=>b.closest('.exercise').remove());document.querySelectorAll('.exercise').forEach(card=>{bindSetRows(card);bindExerciseTimers(card);card.classList.toggle('is-expanded',!card.classList.contains('exercise-done'));const collapse=card.querySelector('[data-collapse-ex]');if(collapse)collapse.onclick=()=>{card.classList.toggle('is-expanded');collapse.textContent=card.classList.contains('is-expanded')?'Minimise':'Expand'};const photo=card.querySelector('[data-photo-note]');if(photo)photo.onchange=()=>{const f=photo.files?.[0];const label=card.querySelector('[data-photo-status]');if(label)label.textContent=f?f.name+' · ready to save':'Attach a photo for this exercise'};const cb=card.querySelector('[data-exdone]');if(cb){cb.addEventListener('change',()=>{const wk=Math.max(1,Math.min(12,Number(document.getElementById('logWeek').value)||activeWeek()));setExerciseChecked(activeWorkout.program,wk,activeWorkout.day,card.dataset.name,cb.checked);card.classList.toggle('exercise-done',cb.checked);card.classList.toggle('is-expanded',!cb.checked);if(collapse)collapse.textContent=cb.checked?'Expand':'Minimise';const group=card.dataset.supersetGroup;if(group){document.querySelectorAll('#workoutExercises .exercise').forEach(peer=>{if(peer!==card&&peer.dataset.supersetGroup===group){const peerCb=peer.querySelector('[data-exdone]');if(peerCb)peerCb.checked=cb.checked;peer.classList.toggle('exercise-done',cb.checked);peer.classList.toggle('is-expanded',!cb.checked);const peerToggle=peer.querySelector('[data-collapse-ex]');if(peerToggle)peerToggle.textContent=cb.checked?'Expand':'Minimise';setExerciseChecked(activeWorkout.program,wk,activeWorkout.day,peer.dataset.name,cb.checked)}})}})}})}
function workoutItemHTML(it,i){const wk=Number(window.viewedWeek)||activeWeek();const isDone=getExerciseChecked(active().name,wk,activeWorkout.day,it.name);const key=it.name.toLowerCase().includes('front squat')?'Front squat':it.name.toLowerCase().includes('back squat')?'Back squat':it.name.toLowerCase().includes('snatch')?'Snatch':it.name.toLowerCase().includes('clean')?'Clean & jerk':null;const sug=Number(it.loadKg)>0?roundWeight(it.loadKg):(it.pct&&key?roundWeight(state.maxes[key]*it.pct/100):0);const isRun=/treadmill|aerobic run/i.test(it.name);const durationSeconds=Math.max(0,Number(it.durationSeconds)||0);const restRaw=String(it.restTimes||it.restSeconds||'').trim();const restList=restRaw.split(/[,;\/]+/).map(x=>Math.max(0,Number(x.trim())||0)).filter(x=>x>0);const restJson=JSON.stringify(restList);const ssStyle=supersetInlineStyle(it.supersetGroup,activeWorkout.items);const ssColor=supersetPalette(it.supersetGroup,activeWorkout.items);return `<div class="exercise ${isDone?'exercise-done':''} ${it.supersetGroup?'superset-exercise':''}"${ssStyle} data-superset-group="${esc(it.supersetGroup||'')}" data-name="${esc(it.name)}" data-suggest="${sug}" data-run="${isRun?1:0}" data-duration-seconds="${durationSeconds}" data-rest-times='${restJson}'><div class="exercisehead"><div><strong>${it.supersetGroup?`<span class="superset-tag">SUPERSET ${[...new Set(activeWorkout.items.map(x=>x.supersetGroup).filter(Boolean))].indexOf(it.supersetGroup)+1}</span> `:''}${esc(it.name)}</strong><div class="prescription">Planned: ${it.sets} × ${esc(it.reps)}${Number(it.loadKg)>0?' · '+roundWeight(it.loadKg)+' kg programmed':(it.pct?' · '+it.pct+'%':'' )}${sug?' · Suggested '+sug+' kg':''}${durationSeconds?' · '+durationSeconds+' sec/set':''}${restList.length?' · Rest '+restList.map(x=>formatTimer(x)).join('/') :''}${it.planNote?' · '+esc(it.planNote):''}</div></div><div style="display:flex;gap:6px;align-items:center"><button type="button" class="btn ghost" data-collapse-ex>${isDone?"Expand":"Minimise"}</button><button class="btn ghost danger" data-remove-ex aria-label="Remove exercise">✕</button></div></div><div class="exercise-collapsible"><div class="field" style="margin-top:10px"><label>Photo note for this exercise</label><input type="file" accept="image/*" capture="environment" data-photo-note><span class="muted small" data-photo-status>Attach a technique or workout photo (optional)</span></div>${isRun?`<div class="formgrid" style="margin-top:10px"><div class="field"><label>Duration (min)</label><input data-runfield="duration" type="number" placeholder="20"></div><div class="field"><label>Distance (km)</label><input data-runfield="distance" type="number" step="0.1" placeholder="Optional"></div><div class="field"><label>Speed (km/h)</label><input data-runfield="speed" type="number" step="0.1" placeholder="Optional"></div><div class="field"><label>Incline (%)</label><input data-runfield="incline" type="number" step="0.5" placeholder="Optional"></div><div class="field wide"><button type="button" class="btn" data-duration-timer="run">▶ Start duration timer</button><div class="timerreadout" data-timer-display>Timer ready</div></div></div>`:`${durationSeconds?`<div class="timerpanel"><button type="button" class="btn" data-duration-timer="exercise">▶ Start ${formatTimer(durationSeconds)} timer</button><div class="timerreadout" data-timer-display>Timer ready</div></div>`:''}<div class="setline"><span class="setnum">Set</span><label>kg</label>${String(it.reps||'').trim()?'<label>Reps</label>':'<label></label>'}<label>RPE</label><span></span></div><div class="setrows">${Array.from({length:Math.min(12,Math.max(1,Number(it.sets)||1))},(_,n)=>setRowHTML(n+1,sug,parseReps(it.reps),!!String(it.reps||'').trim())).join('')}</div>${restList.length?`<div class="timerpanel"><button type="button" class="btn" data-rest-timer>▶ Start rest timer</button><div class="timerreadout" data-rest-display>Rest preset: ${formatTimer(restList[0])}</div><div class="field" style="margin-top:8px"><label>Rest timer override (seconds)</label><input data-rest-override type="number" min="1" placeholder="Use programmed rest"></div></div>`:''}<button class="btn ghost" data-addset style="margin-top:9px;padding:7px 10px;font-size:12px">＋ Add set</button>`}<div class="exercisefoot"><span>Completed</span><label><input type="checkbox" data-exdone ${isDone?'checked':''}> Mark exercise complete</label></div></div>`}
function formatTimer(seconds){seconds=Math.max(0,Math.round(Number(seconds)||0));const m=Math.floor(seconds/60),s=seconds%60;return m?`${m}:${String(s).padStart(2,'0')}`:`${s}s`}
function startCountdown(display,seconds,button,doneText='Time complete'){if(button._timer){clearInterval(button._timer);button._timer=null}let end=Date.now()+Math.max(1,seconds)*1000;const tick=()=>{const left=Math.max(0,Math.ceil((end-Date.now())/1000));display.textContent=left?formatTimer(left):doneText;if(!left){clearInterval(button._timer);button._timer=null;button.textContent='↻ Restart timer';if(navigator.vibrate)navigator.vibrate([200,100,200]);}};button.textContent='■ Stop timer';button.onclick=()=>{if(button._timer){clearInterval(button._timer);button._timer=null;display.textContent='Timer stopped';button.textContent='▶ Start timer';return}startCountdown(display,seconds,button,doneText)};tick();if(end>Date.now())button._timer=setInterval(tick,250)}
function bindExerciseTimers(card){card.querySelectorAll('.timerpanel').forEach(panel=>{if(panel.querySelector('.timerpanel-toggle'))return;const toggle=document.createElement('button');toggle.type='button';toggle.className='btn ghost timerpanel-toggle';toggle.textContent='Minimise';const body=document.createElement('div');body.className='timerpanel-body';while(panel.firstChild){const node=panel.firstChild;if(node===toggle)continue;body.appendChild(node)}panel.append(toggle,body);toggle.onclick=()=>{panel.classList.toggle('is-collapsed');toggle.textContent=panel.classList.contains('is-collapsed')?'Expand':'Minimise'}});const durBtn=card.querySelector('[data-duration-timer]');if(durBtn&&!durBtn.dataset.bound){durBtn.dataset.bound='1';durBtn.onclick=()=>{const display=card.querySelector('[data-timer-display]');let seconds=Number(card.dataset.durationSeconds)||0;if(durBtn.dataset.durationTimer==='run'){const minutes=Number(card.querySelector('[data-runfield="duration"]')?.value)||0;seconds=Math.round(minutes*60)}if(seconds<=0){toast('Enter a duration first');return}startCountdown(display,seconds,durBtn,'Duration complete')}}const restBtn=card.querySelector('[data-rest-timer]');if(restBtn&&!restBtn.dataset.bound){restBtn.dataset.bound='1';restBtn.onclick=()=>{const custom=Number(card.querySelector('[data-rest-override]')?.value)||0;const rests=JSON.parse(card.dataset.restTimes||'[]');const checked=card.querySelectorAll('[data-setcheck].checked').length;const seconds=custom||rests[Math.min(Math.max(checked-1,0),rests.length-1)]||0;if(seconds<=0){toast('Enter rest times in the program or use the override field');return}startCountdown(card.querySelector('[data-rest-display]'),seconds,restBtn,'Rest complete — next set')}}card.querySelectorAll('[data-setcheck]').forEach(b=>{if(b.dataset.restBound)return;b.dataset.restBound='1';b.addEventListener('click',()=>setTimeout(()=>{if(!b.classList.contains('checked'))return;const rests=JSON.parse(card.dataset.restTimes||'[]');if(!rests.length)return;const n=card.querySelectorAll('[data-setcheck].checked').length;const seconds=rests[Math.min(Math.max(n-1,0),rests.length-1)]||0;if(seconds>0){const btn=card.querySelector('[data-rest-timer]');startCountdown(card.querySelector('[data-rest-display]'),seconds,btn,'Rest complete — next set')}},0))})}

function parseReps(x){const m=String(x).match(/\d+/);return m?Number(m[0]):1}function setRowHTML(n,w,r=1,showReps=true){return `<div class="setline setrow" data-original-weight="${w||''}" data-original-reps="${showReps?r:''}"><span class="setnum">${n}</span><input type="number" step="0.5" min="0" data-field="weight" value="${w||''}" placeholder="kg">${showReps?`<input type="number" min="0" data-field="reps" value="${r}" placeholder="reps">`:'<span></span>'}<input type="number" min="1" max="10" data-field="rpe" placeholder="—"><button class="checkbtn" data-setcheck aria-label="Mark set completed">✓</button></div>`}
function bindSetRows(card){card.querySelectorAll('[data-setcheck]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.onclick=()=>{b.classList.toggle('checked');b.setAttribute('aria-pressed',b.classList.contains('checked'))}})}
async function saveWorkout(){try{const date=document.getElementById('logDate').value||new Date().toISOString().slice(0,10),week=Math.max(1,Math.min(12,Number(document.getElementById('logWeek').value)||activeWeek())),notes='';const cards=[...document.querySelectorAll('#workoutExercises .exercise')];let count=0;for(const card of cards){const name=card.dataset.name,run=card.dataset.run==='1',photoFile=card.querySelector('[data-photo-note]')?.files?.[0],photoData=photoFile?await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(photoFile)}):'',base={id:(window.crypto&&crypto.randomUUID)?crypto.randomUUID():String(Date.now()+Math.random()),timestamp:new Date(date+'T12:00:00').getTime(),date,day:activeWorkout.day,week,program:activeWorkout.program,exercise:name,notes,type:'exercise',photoNote:photoData,done:!!card.querySelector('[data-exdone]')?.checked};if(run){const get=k=>card.querySelector(`[data-runfield="${k}"]`)?.value||'';if(!base.done&&!get('duration')&&!get('distance')&&!get('speed'))return;state.logs.push({...base,weight:0,sets:1,reps:1,duration:Number(get('duration'))||0,distance:Number(get('distance'))||0,speed:Number(get('speed'))||0,incline:Number(get('incline'))||0});count++;}else{const rows=[...card.querySelectorAll('.setrow')];const anyMarked=rows.some(row=>row.querySelector('[data-setcheck]')?.classList.contains('checked'));rows.forEach((row,i)=>{const get=k=>row.querySelector(`[data-field="${k}"]`)?.value||'';const checked=!!row.querySelector('[data-setcheck]')?.classList.contains('checked');const weight=Number(get('weight'))||0,reps=Number(get('reps'))||0,hasReps=!!row.querySelector('[data-field="reps"]');const hasValues=hasReps?(String(get('weight')).trim()!==''&&String(get('reps')).trim()!==''):((String(get('weight')).trim()!=='')||checked||base.done);const changed=String(get('weight'))!==String(row.dataset.originalWeight||'')||(hasReps&&String(get('reps'))!==String(row.dataset.originalReps||''));if(anyMarked?!checked:(!hasValues||(!base.done&&!changed)))return;state.logs.push({...base,id:base.id+'-'+i,weight,sets:1,reps:hasReps?reps:0,rpe:Number(get('rpe'))||0,done:checked||base.done||changed,durationSeconds:Number(card.dataset.durationSeconds)||0});count++})}}if(!count){toast('Enter a weight and reps, mark a set complete, or enter treadmill results.');return}if(week<12){cards.forEach(card=>{if(card.dataset.run==='1')return;const name=card.dataset.name;const source=(active().days[activeWorkout.day]?.items||[]).find(it=>String(it.name).trim().toLowerCase()===String(name).trim().toLowerCase());const increment=Number(source?.loadIncrementKg)||0;if(increment<=0)return;const weights=[...card.querySelectorAll('.setrow [data-field=weight]')].map(x=>Number(x.value)||0).filter(x=>x>0);if(!weights.length)return;const next=roundWeight(Math.max(...weights)+increment);state.weekLoads=state.weekLoads||{};state.weekLoads[loadKey(activeWorkout.program,week+1,activeWorkout.day,name)]=next;});}active().week=week;state.week=week;save();closeModal();render();toast(`Saved ${count} training record${count===1?'':'s'} for ${activeWorkout.program}`)}catch(err){console.error('Training HQ save error',err);toast('Could not save workout: '+(err?.message||'unknown error'))}}
function openHistory(){modal('Training history',`<div class="field"><label>Filter by exercise</label><select id="historyFilter"><option value="">All exercises</option>${[...new Set(state.logs.map(l=>l.exercise))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="historyEntries">${historyHTML('')}</div>`,[{label:'Close',cls:'btn primary',action:closeModal},{label:'Export CSV',cls:'btn',action:exportCSV}]);document.getElementById('historyFilter').onchange=e=>document.getElementById('historyEntries').innerHTML=historyHTML(e.target.value)}function historyHTML(f){const logs=[...state.logs].filter(l=>!f||l.exercise===f).sort((a,b)=>b.timestamp-a.timestamp);return logs.length?logs.map(l=>`<div class="logitem"><div class="exercisehead"><strong>${esc(l.exercise)}</strong><button class="btn ghost danger" data-deletelog="${esc(l.id)}">Delete</button></div><div class="logmeta">${esc(l.date)} · ${esc(l.program||'Combined training')} · ${esc(l.day)} · Week ${l.week}</div><div class="logval">${l.weight?`${l.weight} kg × ${l.reps}`:`${l.duration||0} min`}</div></div>`).join(''):'<div class="empty">No matching logs.</div>'}
document.addEventListener('click',e=>{const b=e.target.closest('[data-deletelog]');if(b){const id=b.dataset.deletelog;state.logs=state.logs.filter(l=>l.id!==id);save();const f=document.getElementById('historyFilter')?.value||'';document.getElementById('historyEntries').innerHTML=historyHTML(f);render();toast('Log entry deleted')}});
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}function exportJSON(){download('training-hq-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');toast('Backup exported')}function exportCSV(){const rows=[['date','day','week','exercise','weight_kg','sets','reps','rpe','duration_min','distance_km','speed_kmh','incline_pct','completed','notes'],...state.logs.map(l=>[l.date,l.day,l.week,l.exercise,l.weight||'',l.sets||'',l.reps||'',l.rpe||'',l.duration||'',l.distance||'',l.speed||'',l.incline||'',l.done?'yes':'no',l.notes||''].map(v=>String(v).replace(/"/g,'""')))],csv=rows.map(r=>r.map(v=>`"${v}"`).join(',')).join('\r\n');download('training-hq-logs-'+new Date().toISOString().slice(0,10)+'.csv',csv,'text/csv');toast('CSV exported')}
document.getElementById('saveProfile').onclick=()=>{const bw=Number(document.getElementById('profileBodyweight').value)||'',age=Number(document.getElementById('profileAge').value)||'';if(bw!==''&&bw<=0)return toast('Enter a valid bodyweight');if(age!==''&&(age<1||age>120))return toast('Enter a valid age');state.profile={bodyweight:bw,age};save();toast('Lifter profile saved')};document.getElementById('calculateEstimate').onclick=()=>{const w=Number(document.getElementById('estimateWeight').value),r=Number(document.getElementById('estimateReps').value),bw=Number(state.profile?.bodyweight)||0;if(!(w>0)||!(r>=1&&r<=20)){toast('Enter a weight and 1–20 reps');return}const reps=Math.max(1,Math.floor(r));const vals=reps===1?[w,w,w,w,w]:[w*(1+reps/30),w*36/(37-reps),w*100/(101.3-2.67123*reps),w*Math.pow(reps,0.1),w*100/(52.2+41.9*Math.exp(-0.055*reps))];const est=vals.reduce((a,b)=>a+b,0)/vals.length;document.getElementById('estimateRatio').value=bw?(est/bw).toFixed(2)+'× BW':'—';const out=document.getElementById('estimateResult');out.classList.remove('hidden');out.innerHTML=`<strong>Estimated 1RM: ${est.toFixed(1)} kg</strong><br>${esc(document.getElementById('estimateLift').value)} · ${w} kg × ${reps} reps<br>${bw?`Bodyweight ratio: ${(est/bw).toFixed(2)}× bodyweight<br>`:''}${state.profile?.age?`Age recorded: ${state.profile.age} (not applied to estimate)<br>`:''}<span class="small">Estimate only; formula results vary. Most reliable for 1–10 reps close to failure.</span>`};
document.getElementById('addReferenceMax').onclick=()=>addReferenceMaxRow();document.getElementById('saveMaxes').onclick=()=>{const rows=[...document.querySelectorAll('#referenceMaxRows .reference-max-row')];const next={};for(const row of rows){const name=row.querySelector('[data-ref-name]').value.trim().replace(/\s+/g,' ');const raw=row.querySelector('[data-ref-value]').value;const n=Number(raw);if(!name&&!String(raw).trim())continue;if(!name)return toast('Enter an exercise name for each reference max');if(!(n>0))return toast('Enter a positive maximum for '+name);if(Object.keys(next).some(k=>k.toLowerCase()===name.toLowerCase()))return toast('Duplicate reference max: '+name);next[name]=n;}if(!Object.keys(next).length)return toast('Add at least one reference maximum');state.maxes=next;for(const name of Object.keys(next)){if(!state.exerciseLibrary.some(x=>x.toLowerCase()===name.toLowerCase()))state.exerciseLibrary.push(name);}save();render();toast('Reference maximums saved; lifts added to Exercise Library')};document.getElementById('saveCycle').onclick=()=>{active().week=Math.max(1,Math.min(12,Number(document.getElementById('currentWeek').value)||1));state.week=active().week;state.rounding=Number(document.getElementById('rounding').value)||2.5;save();render();toast('Cycle settings saved')};document.getElementById('exportJson').onclick=exportJSON;document.getElementById('exportCsv').onclick=exportCSV;document.getElementById('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.logs)||!Array.isArray(data.programs)||!data.maxes)throw new Error('Not a Training HQ backup');if(!confirm('Replace current app data with this backup? Export your current data first if you want to keep it.'))return;state=migrateBackup(data);save();render();toast('Backup restored')}catch(err){toast('Import failed: '+err.message)}finally{e.target.value=''}};document.getElementById('resetData').onclick=()=>{if(confirm('Reset ALL programs, logs and settings on this device? Export a backup first if needed.')){state=structuredClone(defaults);selectedDay=dayName(new Date());save();render();navigate('home');toast('App reset')}};
const driveClientInput=document.getElementById('driveClientId');driveClientInput.value=localStorage.getItem('trainingHQ_driveClientId')||'';
document.getElementById('connectDrive').onclick=async()=>{try{const id=driveClientInput.value.trim();if(!id.includes('.apps.googleusercontent.com'))return toast('Enter a valid Google OAuth Web Client ID');localStorage.setItem('trainingHQ_driveClientId',id);await requestDriveToken('consent');const ok=await backupToDrive(false);if(ok){driveButtons(true);driveStatus('Connected · backup saved '+new Date().toLocaleString());toast('Connected to Google Drive and backup saved');}else{driveButtons(true);}}catch(e){driveStatus(e.message);toast('Could not connect or back up: '+e.message);}};
document.getElementById('restoreDrive').onclick=restoreFromDrive;

